"use client";

import { $createParagraphNode, ElementNode } from "lexical";
import type {
  DOMConversionMap,
  DOMConversionOutput,
  DOMExportOutput,
  EditorConfig,
  LexicalNode,
  NodeKey,
  SerializedElementNode,
  Spread,
} from "lexical";

export type CalloutType = "note" | "tip" | "info" | "warning" | "caution";

export type SerializedCalloutNode = Spread<
  {
    calloutType: CalloutType;
    emoji?: string;
  },
  SerializedElementNode
>;

const VALID_CALLOUT_TYPES = new Set<string>([
  "note",
  "tip",
  "info",
  "warning",
  "caution",
]);

const normalizeCalloutType = (type?: string | null): CalloutType => {
  if (type && VALID_CALLOUT_TYPES.has(type.toLowerCase())) {
    return type.toLowerCase() as CalloutType;
  }
  return "note";
};

const convertCalloutElement = (domNode: HTMLElement): DOMConversionOutput => {
  const calloutType = normalizeCalloutType(domNode.dataset.calloutType);
  const emoji = domNode.dataset.calloutEmoji;
  return {
    node: $createCalloutNode(calloutType, emoji),
  };
};

export class CalloutNode extends ElementNode {
  __calloutType: CalloutType;
  __emoji?: string;

  constructor(
    calloutType: CalloutType = "note",
    emoji?: string,
    key?: NodeKey
  ) {
    super(key);
    this.__calloutType = calloutType;
    this.__emoji = emoji;
  }

  static override getType(): string {
    return "callout";
  }

  static override clone(node: CalloutNode): CalloutNode {
    return new CalloutNode(node.__calloutType, node.__emoji, node.__key);
  }

  override createDOM(_config: EditorConfig): HTMLElement {
    const dom = document.createElement("aside");
    dom.classList.add("editor-callout", `editor-callout-${this.__calloutType}`);
    dom.dataset.lexicalCallout = "true";
    dom.dataset.calloutType = this.__calloutType;
    if (this.__emoji) {
      dom.dataset.calloutEmoji = this.__emoji;
    }
    return dom;
  }

  override updateDOM(prevNode: this, dom: HTMLElement): boolean {
    if (prevNode.__calloutType !== this.__calloutType) {
      dom.classList.remove(`editor-callout-${prevNode.__calloutType}`);
      dom.classList.add(`editor-callout-${this.__calloutType}`);
      dom.dataset.calloutType = this.__calloutType;
    }
    if (prevNode.__emoji !== this.__emoji) {
      if (this.__emoji) {
        dom.dataset.calloutEmoji = this.__emoji;
      } else {
        delete dom.dataset.calloutEmoji;
      }
    }
    return false;
  }

  static override importDOM(): DOMConversionMap | null {
    return {
      aside: (domNode: HTMLElement) => {
        if (
          !domNode.classList.contains("editor-callout") &&
          !domNode.dataset.calloutType
        ) {
          return null;
        }
        return {
          conversion: convertCalloutElement,
          priority: 2,
        };
      },
      div: (domNode: HTMLElement) => {
        if (
          !domNode.dataset.lexicalCallout &&
          !domNode.dataset.calloutType &&
          !domNode.classList.contains("editor-callout")
        ) {
          return null;
        }
        return {
          conversion: convertCalloutElement,
          priority: 2,
        };
      },
    };
  }

  override exportDOM(): DOMExportOutput {
    const element = document.createElement("aside");
    element.classList.add(
      "editor-callout",
      `editor-callout-${this.__calloutType}`
    );
    element.dataset.calloutType = this.__calloutType;
    if (this.__emoji) {
      element.dataset.calloutEmoji = this.__emoji;
    }
    return { element };
  }

  static override importJSON(
    serializedNode: SerializedCalloutNode
  ): CalloutNode {
    return $createCalloutNode(
      serializedNode.calloutType,
      serializedNode.emoji
    ).updateFromJSON(serializedNode);
  }

  override exportJSON(): SerializedCalloutNode {
    return {
      ...super.exportJSON(),
      calloutType: this.__calloutType,
      emoji: this.__emoji,
      type: "callout",
      version: 1,
    };
  }

  getCalloutType(): CalloutType {
    return this.__calloutType;
  }

  setCalloutType(type: CalloutType): this {
    const writable = this.getWritable();
    writable.__calloutType = type;
    return writable;
  }

  getEmoji(): string | undefined {
    return this.__emoji;
  }

  setEmoji(emoji?: string): this {
    const writable = this.getWritable();
    writable.__emoji = emoji;
    return writable;
  }

  override canIndent(): boolean {
    return false;
  }

  override collapseAtStart(): boolean {
    const paragraph = $createParagraphNode();
    const children = this.getChildren();
    for (const child of children) {
      paragraph.append(child);
    }
    this.replace(paragraph);
    return true;
  }
}

export function $createCalloutNode(
  calloutType: CalloutType = "note",
  emoji?: string
): CalloutNode {
  return new CalloutNode(calloutType, emoji);
}

export function $isCalloutNode(
  node: LexicalNode | null | undefined
): node is CalloutNode {
  return node instanceof CalloutNode;
}

import type { MultilineElementTransformer } from "@lexical/markdown";
import {
  $createParagraphNode,
  $createTextNode,
  $isElementNode,
  ParagraphNode,
} from "lexical";

import { $createCalloutNode, $isCalloutNode, CalloutNode } from "./node";
import type { CalloutType } from "./node";

const ALERT_START_REGEX =
  /^(?:>\s*)?\[!(?<type>NOTE|TIP|INFO|IMPORTANT|WARNING|CAUTION)\][ \t]?/iu;

const TYPE_MAP: Record<string, CalloutType> = {
  caution: "caution",
  important: "warning",
  info: "info",
  note: "note",
  tip: "tip",
  warning: "warning",
};

export const CALLOUT_MARKDOWN_TRANSFORMER: MultilineElementTransformer = {
  dependencies: [CalloutNode, ParagraphNode],
  export: (node, traverseChildren) => {
    if (!$isCalloutNode(node)) {
      return null;
    }
    const alertType = node.getCalloutType().toUpperCase();
    const childrenText = traverseChildren(node).trim();
    if (!childrenText) {
      return `> [!${alertType}]\n>`;
    }
    const lines = childrenText.split("\n");
    const formattedLines = lines.map((line) => (line ? `> ${line}` : ">"));
    return [`> [!${alertType}]`, ...formattedLines].join("\n");
  },
  handleImportAfterStartMatch: ({ lines, rootNode, startLineIndex }) => {
    const startLine = lines[startLineIndex];
    if (!startLine || !startLine.startsWith(">")) {
      return null;
    }
    const match = ALERT_START_REGEX.exec(startLine);
    if (!match?.groups?.type) {
      return null;
    }
    const rawType = match.groups.type.toLowerCase();
    const calloutType: CalloutType = TYPE_MAP[rawType] ?? "note";

    const contentLines: string[] = [];
    const inlineRemainder = startLine.slice(match[0].length).trim();
    if (inlineRemainder) {
      contentLines.push(inlineRemainder);
    }

    let lineIndex = startLineIndex + 1;

    while (lineIndex < lines.length) {
      const line = lines[lineIndex];
      if (line === undefined || !line.startsWith(">")) {
        break;
      }
      contentLines.push(line.replace(/^>\s?/u, ""));
      lineIndex += 1;
    }

    const calloutNode = $createCalloutNode(calloutType);
    if (contentLines.length === 0) {
      calloutNode.append($createParagraphNode());
    } else {
      const paragraph = $createParagraphNode();
      paragraph.append($createTextNode(contentLines.join("\n")));
      calloutNode.append(paragraph);
    }

    rootNode.append(calloutNode);
    return [true, Math.max(startLineIndex, lineIndex - 1)];
  },
  regExpEnd: {
    optional: true,
    regExp: /^$/u,
  },
  regExpStart: ALERT_START_REGEX,
  replace: (
    rootNode,
    children,
    startMatch,
    _endMatch,
    linesInBetween,
    isImport
  ) => {
    const rawType =
      (startMatch as RegExpMatchArray).groups?.type?.toLowerCase() ??
      startMatch[1]?.toLowerCase();
    const calloutType: CalloutType = TYPE_MAP[rawType ?? ""] ?? "note";

    const calloutNode = $createCalloutNode(calloutType);
    const paragraph = $createParagraphNode();

    if (children && children.length > 0) {
      let hasInline = false;
      for (const child of children) {
        if ($isElementNode(child)) {
          if (hasInline) {
            calloutNode.append(paragraph);
            hasInline = false;
          }
          calloutNode.append(child);
        } else {
          paragraph.append(child);
          hasInline = true;
        }
      }
      if (hasInline || calloutNode.getChildrenSize() === 0) {
        calloutNode.append(paragraph);
      }
    } else if (linesInBetween && linesInBetween.length > 0) {
      paragraph.append($createTextNode(linesInBetween.join("\n")));
      calloutNode.append(paragraph);
    } else {
      calloutNode.append(paragraph);
    }

    if (isImport) {
      rootNode.append(calloutNode);
    } else {
      rootNode.replace(calloutNode);
      const target = calloutNode.getFirstChild() ?? calloutNode;
      target.selectStart();
    }
  },
  type: "multiline-element",
};

import { createCommand } from "lexical";

import type { CalloutType } from "../../core/nodes/callout/node";

export interface InsertCalloutPayload {
  emoji?: string;
  targetNodeKey?: string;
  type?: CalloutType;
}

export const INSERT_CALLOUT_COMMAND = createCommand<
  InsertCalloutPayload | undefined
>("INSERT_CALLOUT_COMMAND");

import type { ElementNode } from "lexical";
import {
  AlertTriangleIcon,
  InfoIcon,
  LightbulbIcon,
  ShieldAlertIcon,
} from "lucide-react";

import { CalloutNode } from "../../core/nodes/callout/node";
import type { CalloutType } from "../../core/nodes/callout/node";
import { CALLOUT_MARKDOWN_TRANSFORMER } from "../../core/nodes/callout/transformer";
import type { ExtraEditorFeature } from "../../core/types";
import { replaceCurrentBlock } from "../slash-command/utils";
import { CalloutPlugin } from "./plugin";
import { replaceElementWithCallout } from "./utils";

const applyCalloutCommand =
  (type: CalloutType = "note") =>
  (targetElement: ElementNode): void => {
    replaceElementWithCallout(targetElement, type);
  };

export const calloutFeature: ExtraEditorFeature = {
  id: "callout",
  nodes: [CalloutNode],
  plugin: CalloutPlugin,
  slashCommands: [
    {
      command: {
        description: "Highlighted callout box",
        icon: InfoIcon,
        id: "callout",
        keywords: ["callout", "note", "alert", "box", "info"],
        label: "Callout",
      },
      run: (editor) => {
        replaceCurrentBlock(editor, applyCalloutCommand("note"));
      },
    },
    {
      command: {
        description: "Helpful tip callout",
        icon: LightbulbIcon,
        id: "tip",
        keywords: ["tip", "hint", "callout", "idea"],
        label: "Tip",
      },
      run: (editor) => {
        replaceCurrentBlock(editor, applyCalloutCommand("tip"));
      },
    },
    {
      command: {
        description: "Warning alert callout",
        icon: AlertTriangleIcon,
        id: "warning",
        keywords: ["warning", "alert", "caution", "callout"],
        label: "Warning",
      },
      run: (editor) => {
        replaceCurrentBlock(editor, applyCalloutCommand("warning"));
      },
    },
    {
      command: {
        description: "Critical caution callout",
        icon: ShieldAlertIcon,
        id: "caution",
        keywords: ["caution", "danger", "critical", "callout"],
        label: "Caution",
      },
      run: (editor) => {
        replaceCurrentBlock(editor, applyCalloutCommand("caution"));
      },
    },
  ],
  transformers: [CALLOUT_MARKDOWN_TRANSFORMER],
};

"use client";

import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import { $findMatchingParent, mergeRegister } from "@lexical/utils";
import {
  $createParagraphNode,
  $getSelection,
  $isRangeSelection,
  COMMAND_PRIORITY_LOW,
  INSERT_PARAGRAPH_COMMAND,
  KEY_BACKSPACE_COMMAND,
} from "lexical";
import { useEffect } from "react";

import { $isCalloutNode, CalloutNode } from "../../core/nodes/callout/node";
import { INSERT_CALLOUT_COMMAND } from "./commands";
import { insertCallout } from "./utils";

export function CalloutPlugin() {
  const [editor] = useLexicalComposerContext();

  useEffect(() => {
    if (!editor.hasNodes([CalloutNode])) {
      throw new Error(
        "CalloutPlugin: CalloutNode is not registered on the editor"
      );
    }

    return mergeRegister(
      editor.registerCommand(
        INSERT_CALLOUT_COMMAND,
        (payload) => {
          insertCallout(payload?.type, payload?.emoji, payload?.targetNodeKey);
          return true;
        },
        COMMAND_PRIORITY_LOW
      ),
      editor.registerCommand(
        INSERT_PARAGRAPH_COMMAND,
        () => {
          const selection = $getSelection();
          if (!$isRangeSelection(selection) || !selection.isCollapsed()) {
            return false;
          }

          const anchorNode = selection.anchor.getNode();
          const calloutNode = $findMatchingParent(anchorNode, $isCalloutNode);
          if (!$isCalloutNode(calloutNode)) {
            return false;
          }

          const topLevelBlock = anchorNode.getTopLevelElementOrThrow();
          // If the cursor is on an empty paragraph at the very end of the callout,
          // pressing Enter exits the callout and creates a new paragraph below it.
          if (
            topLevelBlock === calloutNode.getLastChild() &&
            topLevelBlock.getTextContent().length === 0 &&
            calloutNode.getChildrenSize() > 1
          ) {
            topLevelBlock.remove();
            const newParagraph = $createParagraphNode();
            calloutNode.insertAfter(newParagraph);
            newParagraph.select();
            return true;
          }

          return false;
        },
        COMMAND_PRIORITY_LOW
      ),
      editor.registerCommand(
        KEY_BACKSPACE_COMMAND,
        () => {
          const selection = $getSelection();
          if (
            !$isRangeSelection(selection) ||
            !selection.isCollapsed() ||
            selection.anchor.offset !== 0
          ) {
            return false;
          }

          const anchorNode = selection.anchor.getNode();
          const calloutNode = $findMatchingParent(anchorNode, $isCalloutNode);
          if (!$isCalloutNode(calloutNode)) {
            return false;
          }

          // If callout is completely empty or caret is at start of first empty paragraph,
          // unwrapping it to a regular paragraph
          if (calloutNode.getTextContent().trim().length === 0) {
            const paragraph = $createParagraphNode();
            calloutNode.replace(paragraph);
            paragraph.select();
            return true;
          }

          return false;
        },
        COMMAND_PRIORITY_LOW
      )
    );
  }, [editor]);

  return null;
}

import { $insertNodeToNearestRoot } from "@lexical/utils";
import {
  $createParagraphNode,
  $getNodeByKey,
  $getSelection,
  $isElementNode,
  $isRangeSelection,
} from "lexical";
import type { ElementNode } from "lexical";

import { $createCalloutNode } from "../../core/nodes/callout/node";
import type { CalloutType } from "../../core/nodes/callout/node";

export const createCalloutStructure = (
  type: CalloutType = "note",
  emoji?: string
) => {
  const paragraph = $createParagraphNode();
  const calloutNode = $createCalloutNode(type, emoji);
  calloutNode.append(paragraph);
  return {
    calloutNode,
    paragraph,
  };
};

export const replaceElementWithCallout = (
  targetElement: ElementNode,
  type: CalloutType = "note",
  emoji?: string
) => {
  const calloutNode = $createCalloutNode(type, emoji);
  const children = targetElement.getChildren();
  if (children.length > 0) {
    for (const child of children) {
      calloutNode.append(child);
    }
  } else {
    calloutNode.append($createParagraphNode());
  }
  targetElement.replace(calloutNode);
  calloutNode.selectEnd();
};

export const insertCallout = (
  type: CalloutType = "note",
  emoji?: string,
  targetNodeKey?: string
) => {
  if (targetNodeKey) {
    const targetNode = $getNodeByKey(targetNodeKey);
    if (!$isElementNode(targetNode)) {
      return false;
    }
    replaceElementWithCallout(targetNode, type, emoji);
    return true;
  }

  const selection = $getSelection();
  if ($isRangeSelection(selection)) {
    const targetElement = selection.anchor
      .getNode()
      .getTopLevelElementOrThrow();
    replaceElementWithCallout(targetElement, type, emoji);
    return true;
  }

  const { calloutNode, paragraph } = createCalloutStructure(type, emoji);
  $insertNodeToNearestRoot(calloutNode);
  paragraph.selectEnd();
  return true;
};
